=== shipping/TransLogAdapter.java
     1	package com.loja.shipping;
     2	
     3	import com.fasterxml.jackson.databind.ObjectMapper;
     4	import java.net.HttpURLConnection;
     5	import java.net.URL;
     6	import java.nio.charset.StandardCharsets;
     7	
     8	public class TransLogAdapter implements ShippingCarrier {
     9	    private final String baseUrl;
    10	    private static final int TIMEOUT_MS = 2000;
    11	    private final ObjectMapper mapper = new ObjectMapper();
    12	
    13	    public TransLogAdapter(String baseUrl) {
    14	        this.baseUrl = baseUrl;
    15	    }
    16	
    17	    @Override
    18	    public ShippingQuote getQuote(String zipCode, Double weightGrams) {
    19	        return getQuoteWithService(zipCode, weightGrams, "STD");
    20	    }
    21	
    22	    public ShippingQuote getQuoteWithService(String zipCode, Double weightGrams, String service) {
    23	        try {
    24	            String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
    25	                baseUrl, zipCode, weightGrams.intValue(), service);
    26	
    27	            HttpURLConnection conn = (HttpURLConnection) new URL(url).openConnection();
    28	            conn.setConnectTimeout(TIMEOUT_MS);
    29	            conn.setReadTimeout(TIMEOUT_MS);
    30	            conn.setRequestMethod("GET");
    31	
    32	            if (conn.getResponseCode() == 200) {
    33	                String response = new String(conn.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
    34	                return mapper.readValue(response, ShippingQuote.class);
    35	            }
    36	
    37	            ShippingQuote quote = new ShippingQuote();
    38	            quote.error = "CARRIER_UNAVAILABLE";
    39	            return quote;
    40	
    41	        } catch (Exception e) {
    42	            ShippingQuote quote = new ShippingQuote();
    43	            quote.error = "CARRIER_UNAVAILABLE";
    44	            return quote;
    45	        }
    46	    }
    47	}

