     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	
     7	public class CreditCardPayment implements PaymentStrategy {
     8	    private static final double MONTHLY_RATE = 0.0199;
     9	
    10	    @Override
    11	    public Double calculateAdjustment(Double subtotal, Integer installments) {
    12	        if (installments <= 3) {
    13	            return 0.0;
    14	        }
    15	
    16	        double monthlyRate = MONTHLY_RATE;
    17	        double numerator = monthlyRate;
    18	        double denominator = 1.0 - Math.pow(1.0 + monthlyRate, -installments);
    19	        double installmentValue = subtotal * (numerator / denominator);
    20	
    21	        Double totalWithInterest = Money.round(installmentValue * installments);
    22	        Double interestAmount = totalWithInterest - subtotal;
    23	
    24	        return Money.round(interestAmount);
    25	    }
    26	
    27	    @Override
    28	    public boolean isApplicable(Double totalValue, Integer installments) {
    29	        return installments >= 1 && installments <= 12;
    30	    }
    31	
    32	    @Override
    33	    public Integer getMaxInstallments() {
    34	        return 12;
    35	    }
